<?= $this->extend('layouts/main') ?><?= $this->section('content') ?>
<nav class="breadcrumbs"><a href="<?= site_url('pecas') ?>">Peças</a><span>/</span><span><?= esc($piece['code']) ?></span></nav>
<div class="page-head"><div><span class="badge"><?= esc($piece['status']) ?></span><h1><?= esc($piece['title']) ?></h1><p><?= esc($piece['summary']) ?></p></div><div class="page-head-actions"><a class="button cancel-button" href="<?= esc($backUrl) ?>">Voltar</a><?php foreach (['previous' => ['Anterior', '&lt;'], 'next' => ['Próximo', '&gt;']] as $direction => [$label, $icon]): ?><?php if ($neighborUrls[$direction]): ?><a class="button secondary" href="<?= esc($neighborUrls[$direction]) ?>" aria-label="<?= esc($label) ?>" title="<?= esc($label) ?>"><span aria-hidden="true"><?= $icon ?></span></a><?php else: ?><button class="button secondary" type="button" disabled aria-label="<?= esc($label) ?>" title="<?= esc($label) ?>"><?= $icon ?></button><?php endif ?><?php endforeach ?></div></div>
<?= $this->include('pieces/rename') ?>
<div class="piece-detail-layout"><div><dl class="metadata"><div><dt>Código</dt><dd><?= esc($piece['code']) ?></dd></div><div><dt>Comunidade</dt><dd><?= esc($piece['project_name']) ?></dd></div><div><dt>Tipo</dt><dd><?= esc($piece['type']) ?></dd></div><div><dt>Visibilidade</dt><dd><?= esc($piece['visibility']) ?></dd></div><div><dt>Público</dt><dd><?= esc($piece['audience'] ?: 'Não informado') ?></dd></div><div><dt>Finalidade</dt><dd><?= esc($piece['pedagogical_purpose'] ?: 'Não informada') ?></dd></div></dl>
<section class="panel keyword-manager" aria-labelledby="keywords-title"><div class="section-head"><h2 id="keywords-title">Palavras-chave</h2></div><?php if ($canManageKeywords): ?><form method="post" action="<?= site_url('pecas/'.$piece['id'].'/palavras-chave') ?>" class="stack" data-keyword-autosave><?= csrf_field() ?><fieldset><legend>Palavras-chave disponíveis</legend><?php if ($terms): ?><div class="piece-term-options"><?php $currentCategory = null; ?><?php foreach ($terms as $term): ?><?php if ($currentCategory !== $term['vocabulary_id']): ?><?php if ($currentCategory !== null): ?></div></div><?php endif ?><?php $currentCategory = $term['vocabulary_id']; ?><div class="piece-term-group"><strong><?= esc($term['vocabulary_name']) ?></strong><div><?php endif ?><label><input type="checkbox" name="term_ids[]" value="<?= esc($term['id']) ?>" <?= in_array($term['id'], $selectedTermIds, true) ? 'checked' : '' ?>> <?= esc($term['label']) ?></label><?php endforeach ?></div></div></div><?php else: ?><p class="muted">Nenhuma palavra-chave cadastrada.</p><?php endif ?></fieldset><?php if ($canManageCategories): ?><details class="keyword-create"><summary class="button secondary">Nova categoria (+)</summary><div class="new-keyword-fields"><label>Categoria<select name="vocabulary_id"><option value="">Selecione uma categoria</option><?php foreach ($vocabularies as $vocabulary): ?><option value="<?= esc($vocabulary['id']) ?>"><?= esc($vocabulary['name']) ?></option><?php endforeach ?></select></label><label>Nova categoria<input type="text" name="new_category" maxlength="190" placeholder="Cria e seleciona uma categoria"></label><label>Nova palavra-chave<input type="text" name="new_keyword" maxlength="190"></label></div><p class="form-help">Desmarque uma palavra-chave para removê-la desta peça. O termo continuará disponível na comunidade.</p><button class="button" type="submit">Salvar palavras-chave</button></details><?php else: ?><noscript><button class="button" type="submit">Salvar palavras-chave</button></noscript><?php endif ?></form><?php else: ?><div class="piece-keywords"><?php foreach ($terms as $term): ?><?php if (in_array($term['id'], $selectedTermIds, true)): ?><span><?= esc($term['label']) ?></span><?php endif ?><?php endforeach ?><?php if (! $selectedTermIds): ?><span class="no-keywords">Sem palavras-chave</span><?php endif ?></div><?php endif ?></section>
<section class="panel"><div class="section-head"><h2>Ativos</h2></div><?php foreach ($assets as $asset): ?><article class="asset-row"><div><strong><?= esc($asset['name']) ?></strong><span><?= esc($asset['type']) ?> · <?= esc($asset['version_count']) ?> versão(ões)</span></div><a href="<?= site_url('ativos/'.$asset['id'].'/versoes/nova') ?>">Nova versão</a></article><?php endforeach ?><?php if (!$assets): ?><div class="empty"><p>Esta peça ainda não possui ativos.</p><a href="<?= site_url('pecas/'.$piece['id'].'/ativos/novo') ?>">Adicionar o primeiro ativo</a></div><?php endif ?></section></div>
<aside class="panel piece-preview" aria-labelledby="preview-title"><div class="section-head"><h2 id="preview-title">Pré-visualização</h2></div><?php if ($previewFile && $previewType === 'image'): ?><?= $this->include('pieces/image_preview') ?><?php elseif ($previewFile && $previewType === 'video'): ?><video controls preload="metadata"><source src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" type="<?= esc($previewFile['mime_type']) ?>">Seu navegador não consegue reproduzir este vídeo.</video><?php elseif ($previewFile && $previewType === 'audio'): ?><div class="audio-preview"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><audio controls preload="metadata"><source src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" type="<?= esc($previewFile['mime_type']) ?>">Seu navegador não consegue reproduzir este áudio.</audio></div><?php elseif ($previewFile && $previewType === 'pdf'): ?><iframe src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" title="Pré-visualização de <?= esc($piece['title']) ?>"></iframe><?php elseif ($previewFile): ?><div class="preview-unavailable"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><p>Pré-visualização indisponível para este formato.</p></div><?php else: ?><div class="preview-unavailable"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><p>Nenhum arquivo disponível para pré-visualização.</p></div><?php endif ?><?php if ($previewFile): ?><?php $originalFilename = $piece['original_filename'] ?: $previewFile['original_name']; ?><?php $originalPath = $piece['original_directory'] ? rtrim($piece['original_directory'], '/\\').'/'.$previewFile['original_name'] : $previewFile['original_name']; ?><dl class="preview-file-metadata"><div><dt>Nome do arquivo</dt><dd><?= esc($originalFilename) ?></dd></div><div><dt>Versão do arquivo</dt><dd><?= esc($previewFile['version_number']) ?></dd></div><div><dt>Caminho original</dt><dd><?= esc($originalPath) ?></dd></div></dl><?php endif ?><?= $this->include('pieces/image_description') ?></aside></div>
<script src="<?= base_url('assets/js/piece-keywords.js') ?>" defer></script>
<?= $this->endSection() ?>
